WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (354::BIGINT, 'El profe no explica bien algunos temas no los cubre. Si quiere pasar vayan a la tutorias que se entiende más que en la clase. El asistente explica demasiado.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2026-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'ddf206640abae1ac3367607b73632dc5c9a2f51c1bc3d5cf451b988422e3cb7a'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'No lo recomiendo para nada, pero diay es el único profe que da el curso, tenga la materia al día, vaya a consulta, no se deje asustar por sus comentarios. Al preguntarle algo siempre se va por las ramas, por lo que intente ser autodidacta.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases largas']::TEXT[], '2026-06-21T00:00:00+00:00'::TIMESTAMPTZ, '6356ae192099e72421ce8d5a461cf75fffb6f89a343f9ee95797275b288096f3'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'No lo recomiendo, es un fanfarrón que le gusta llamar la atención, hace monadas según él para explicar pero lo que hace es generar confusión. No es claro, un tema fácil lo hace complicado. Al preguntársele por algo se va por las nubes y se enreda y lo enreda a uno. Los examenes mal medidos en tiempo'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2026-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'f579fdba5824a80a295302a78a4066f1859257dfc1c72356f56abcd29362489c'::TEXT, ARRAY[1182]::BIGINT[]),
    (354::BIGINT, 'El profe como tal no es malo y el curso si usted le mete las 6 horas se logra. Ir a consulta es indispensable y llevar la materia al dia si usted quiere llegar bien al examen.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2025-12-08T00:00:00+00:00'::TIMESTAMPTZ, '0e43f3da0cc894081aa334654150519885cccf9fecee0deeb4b4ec9716c4f13e'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'No se logra explicar para los temas y menos para el último examen. No tiene una actitud mala (se le pueden proponer aspectos de calificación) pero no sabe explicar bien ningún tema y siempre pierde tiempo hablando de otras cosas nada que ver con el curso. Si usted es 100% autodidacta/o, se logra.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2025-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'fadf142c35345c508e9bda3b533d8e44b7510db0219b21351457f6db391aeaba'::TEXT, ARRAY[1182]::BIGINT[]),
    (354::BIGINT, 'Los informes son sumamente largos, da las notas a lo último, por lo que no se tiene una noción de como van tus notas, basicamente ir a consulta es OBLIGATORIO, porque si no se enoja, Sabe mucho, pero es Narcisista entonces es muy pesado el curso, es 1 crédito, pero realmente son como 7.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2025-07-17T00:00:00+00:00'::TIMESTAMPTZ, '3a33de3f712e0551775874001ac9a8f504f22b79f2e860f77fb00aabe2cdcdb7'::TEXT, ARRAY[1199]::BIGINT[]),
    (354::BIGINT, 'Vea quedarse es difícil pero si hay que ponerle bastante. Consiga materia y ejercicios de otros semestres por que el profe no explica bien lo que es práctico. Teoría el profe sabe un motón y lo explica muy bien. Pero le gusta meter miedo y es un irresponsable no se dejen!!! Necio para pedir cosas.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, '5af1f6d6fe0e35dfea3702cf92dfceb3ac4fae427325ed7ccb1b05ff120c9d60'::TEXT, ARRAY[1198, 1199]::BIGINT[]),
    (354::BIGINT, 'No explica bien, no ayuda mucho cuando uno va a consulta. Complica un curso tan sencillo como lo es concreto.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-05-21T00:00:00+00:00'::TIMESTAMPTZ, 'c502ef88d951a082f724377ca241ef76e87e2614fdc5b9a92560213958c90491'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'Explica bien, sin embargo suele utilizar demasiadas analogías que pueden ser confusas, pero tiene muchos conocimientos en el tema. Hace que el curso sea difícil, los exámenes son algo difíciles pero yendo bastante preparado se logra, tengan cuidado algunas ideas que propone con respecto a las evalua'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2025-02-19T00:00:00+00:00'::TIMESTAMPTZ, '5270272094538ba43f1cd5c7511deca2118010bc82da8204eacc6352defdfe7e'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'La materia en sí no es difícil, pero el mae lo complica. Mantenga las cosas al día y preste atención en clase, no es como lo pintan que es dificilísimo de pasar. Eso sí, ármese de paciencia porque dura más de un mes revisando exámenes...'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Exámenes retadores']::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, '2c1eda03b9be3a98369ec76a74fdd079c4bb971bd4b999637542d4ad01866d21'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'Hay que estar preparado para todas las clases, con todas las normas, se las tiene que saber. Los quices los suele hacer algo complicados, los informes son largos, por lo que recomiendo que los trabajen desde que se terminan los ensayos.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Muchos exámenes']::TEXT[], '2024-11-07T00:00:00+00:00'::TIMESTAMPTZ, '4f8e3dd753bf8f1036237d638638984a0c34367c8d7224809f39cba24b03cb48'::TEXT, ARRAY[1199]::BIGINT[]),
    (354::BIGINT, 'La verdad creo que para este semestre mejoró bastante. En concreto solo se dedica a hacer analogías que nadie entiende y no aportan nada a los temas que se ven, sumamente lerdo revisando exámenes y asignaturas, pero no califica tan duro. En lab prepárese para tener que saberse las normas a dedo'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'aa85d22dba9a14d59081b6fef6a09c967fa2b13190dc9e7c234e9dbd5c7ed507'::TEXT, ARRAY[1198, 1199]::BIGINT[]),
    (354::BIGINT, 'El profesor sabe de la materia. Toma mucho tiempo para entregar los exámenes y el proyecto es calificado como competencia. Comiencen el proyecto temprano y hagan propuestas si no les va bien en algunos trabajos, pero todo con buena anticipación (no después de entregada las notas finales).'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2023-07-07T00:00:00+00:00'::TIMESTAMPTZ, 'aaf317acc2163647d325ae077ef1a56c9a9a8bb565c26878ac1e6e68ca93bd5a'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'Al principio se muestra simpático, pero sus rubricas son malísimas solo le gusta escupir conocimiento, sus clases están llenas de analogías que no aportan casi nada y los proyectos son literalmente competencias donde solo 1 puede sacar 100, califica super tarde, en resumen lo peor de la escuela'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'bd9793199e8bdc9c56d81859807d15ac96cebe5e195738df94e36d99d432a141'::TEXT, ARRAY[1198, 1199]::BIGINT[]),
    (354::BIGINT, 'Deben tener cuidado ya que al principio se comporta muy simpático y hace muchos acuerdos en los que ustedes son los afectados. No regala nada. El proyecto es muy duro y es una competencia de todos contra todos.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'd66aa000e3145805924d4cfd581d6f1060e824e3521c4cabc46ce47a425b9f7e'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'Un chiste de profesor. Le encanta escucharse hablar y eso es todo lo que sabe hacer. No ayuda en nada con el proyecto de concreto y las evaluaciones tienen las rúbricas super ambiguas que cambian cada día. Lo peor de la escuela, realmente arruina una materia que podría ser muy ak7.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'ba57b91ed8d606a4ab23722bd4fce692d2f63c932d031bb5a1579c0b64c2c78c'::TEXT, ARRAY[1198, 1199]::BIGINT[]),
    (354::BIGINT, 'Se enreda solo, y las notas las entrega tardísimo dando la escusa de que tiene el horario llenisimo pero da un sermón siempre de manejo del horario y ni el mismo lo hace'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Muchos proyectos grupales']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '131f94293ea34222aeba5b28f31af28cefe4ef88ecd93be440d8b3314e260e69'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'Le encanta escupir conocimiento y tirar una mirada, no enseña muy bien, si uno le pide ayuda o que haga mas ejemplos se va por otros caminos en lugar de explicar el punto en si.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-09-23T00:00:00+00:00'::TIMESTAMPTZ, '52588b7f3acfb684eb2c85d5dfec8b0e9d43b591ddecf07591e17325bbd519b5'::TEXT, ARRAY[1198, 1199]::BIGINT[]),
    (354::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '03bf3ec6a22abce82218c3ce2985570a5c53ed92a24687f4f98abb791a1c05c4'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'El profe explica excelente. Lo único es que califica muy duro, de igual manera el asistente. Las notas las entrega el último día, como recomendación insistir en que las entregue en el tiempo establecido.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2022-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e438d229a277a12ad5a81acb7d73a677a7dcf7f202cece613b732a55a55d1793'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'El profesor tiene mucho conocimiento en todo lo que respecta al concreto, pero muchas veces no era claro en lo que explicaba cosa que repercudía en los exámenes que también eran muy largos y el tiempo nunca alcanzaba.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2022-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'caef1448f08cf762b8816436cdb4330356ea53ffbb58e16ab115b698ba217e25'::TEXT, ARRAY[1198, 1199]::BIGINT[]),
    (354::BIGINT, 'Los examenes son muy dificiles y califica muy duro, en tareas e informes trate de ir a consulta ayuda un montón. Siempre entrega las notas hasta el final del curso'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2022-01-10T00:00:00+00:00'::TIMESTAMPTZ, '9c7b91af4e65f466543d0fe0148e0bf76dfe01fa78f9d6a6fa1e8773e9049ca7'::TEXT, ARRAY[1198, 1199]::BIGINT[]),
    (354::BIGINT, 'Lo peor de la escuela, pero no hay de otra es el unico que lo da'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2022-01-03T00:00:00+00:00'::TIMESTAMPTZ, '25eac4d90d8994cb10e415f37e8b33e2a9c5b55cb78e52bf5abe8fcf574edeb5'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'Irresponsable, juega de pura vida pero no lo es, al reclamarle y fundamentar las cosas desvía el tema y lo agarra a uno entre ojos si lo hace. de lo peor de la escuela. El problema es que es el único que da los cursos.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2021-11-17T00:00:00+00:00'::TIMESTAMPTZ, '561a9ddc2f7da599c9bcaec4ea8170c3132e84f1b217fab250f4614b46526fe4'::TEXT, ARRAY[1198, 1199]::BIGINT[]),
    (354::BIGINT, 'Pésimo profesor, de los peores de la escuela; entrega todas las notas al final y califica super rudo. No es claro con lo que quiere. prepárese para estudiar'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'da38b74e356912ff25d4f64b04041b1b536d1fa74cf25ad921f0376e9d951ece'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'Muy buen profe, pero tiene un gran defecto, que ojalá mejore, y es la entrega de evaluaciones. Nos entregó notas al puro final. No hay que dejarse que siga haciendo eso, el problema es que da vara reclamarle algo porque he escuchado que lo agarra entre ojos.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '3ccabc5ac7b97ebb28b7094ccabd87084e4559ca620548f38e02eb9ccba798c8'::TEXT, ARRAY[1199]::BIGINT[]),
    (354::BIGINT, 'Si se aprende con la clase de concretos, casi siempre se extiende en media hora la clase, da pocos ejemplos. En lab se va a leer normas, con los informes en muchas ocasiones ni el profe sabe lo que quiere. Accesible para pasar entregas. Muy hablador con respecto a las notas y las entrega hasta final'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, '0dfcd31cd8ae7b9fe801aae272ef1a19e879b8979943b96d567dd1b729f1e25f'::TEXT, ARRAY[1198, 1199]::BIGINT[]),
    (354::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '8fe3b9d5396a7088cb9cb700431063ec18a51ef822855c9a3bf18b4fffc02ccb'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'irresposable, hablador, entregó las notas el mismo día de la entrega de actas y quices que hicimos a principios de semestre los revisó hasta ahora, todo lo revisó a la carrea. La materia del curso muy bonita, pero el profe le quita las ganas a uno.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'b13ffdfacb25caaf39df53f8658877f2c16d8ce686818e466a877ffce36cf3ce'::TEXT, ARRAY[1198, 1199]::BIGINT[]),
    (354::BIGINT, 'explica mal, juega de responsable pero es lo inverso, entrega todo tarde, hay que estudiar de otros lados porque la materia de examen nunca la explica claramente'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-09T00:00:00+00:00'::TIMESTAMPTZ, '1636d67b29c97a851ec44afadd26d211a57898992144479dc343eb4b4cd42c42'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Exámenes retadores']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'a75f7c2d0f085b95d7a5b3af432a439185d9a890323e5027da81af2404a2b457'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'Sabe mucho, pero a veces se pasa en especial con el proyecto poniendo rubros de calificación que nada que ver. En la parte del examen se pasa si se estudia y por lo general queda clara la información. Con las tareas depende del semestre puede poner tareas decentes o muy pesadas.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'f7bf005db542e59ecba5eddafdd1bca5fb10cd4f94c0be2218b71163d4fb1c8f'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'Es muy exigente con los informes, no entrega las calificaciones y el exámen final lo hace en grupos. Se preocupa por que uno aprenda y siempre que uno necesite ayuda, el esta dispuesto a ayudar. Uno de los mejores profes que tiene la escuela.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, '3914d61fc08974617860d781366a26f9222503dd3c84257b0e73ff35f9020c3e'::TEXT, ARRAY[1199]::BIGINT[]),
    (354::BIGINT, 'De los mejores profes de la escuela, se interesa mucho por sus estudiantes, trata de dar la materia lo más claro posible, lo único es que normalmente se extiende la clase, fuera de eso es un profe muy inspiracional. Volvería a llevar el curso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases largas']::TEXT[], '2018-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'e5dccef99ad7df641567a26d8d29a0920c49fb3a325d06906a69c2df5c1fc296'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'El profe como persona es una teja, pero suele ser bastante irresponsable con las fechas y las entregas de notas, de ahí en fuera en el curso se aprende muchísimo, porque el profe tiene toda la técnica para hacer que los estudiantes le pongan muchísima atención'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'a24fb19910ab874209f03beaaaf2584bd4e53faef6381f4e44f6c607a2511d1e'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'El profe ama su curso. Sabe demasiado sobre el concreto. Él se vuela demasiado en los proyectos que realiza y eso se refleja en las evaluaciones que nos asigna. Es muy impuntual y le gusta ver sufrir al estudiante en el examen final. A pesar de todo, inspira a realizar proyectos locos.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'a17317eb36ea5620b0509a1645ede2ed09f6bce0e6df905ad47ff0e7f75a2f12'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'Es un buen profesor y profesional, pero tiene aspectos que se pueden mejorar como la organización del proyecto final de curso y el cumplimiento del cronograma. Los exámenes son lo usual ni difíciles ni fáciles en cuanto a la materia es bueno llevarla al día.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '951dac249c0e36534785556939c6f331c6e5da9e9d4c45ad241a8628debf238f'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'Realmente aprendí en el curso, es bastante interesante! El profe explica de una buena forma y hasta que a todos les quede claro. Es desordenado con el cronograma y los exámenes son algo de cuidado con los detalles'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2017-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'ae7ef708aa8c491ae97e65d79b6b4a365361674aafdb3a622a855d2def83d958'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'El profesor le encanta hablar pero la materia más difícil casi no la explica, es muy irresponsable para cumplir con el cronograma y siempre se extienden las clases al menos media hora más. Considero que no respeta el tiempo de los demás. Pero a pesar de eso él sabe muchísimo.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-29T00:00:00+00:00'::TIMESTAMPTZ, '5f64d28b07bc76ed8c4e9c947b54afa5425856f7edc80f075eb74c4a3c3d79d3'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'Se interesa en el estudiante, califica durillo, examen es dificiles, no da muchos ejemplos, pero es buen profesor'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2016-06-01T00:00:00+00:00'::TIMESTAMPTZ, '4cd477f58c22cdb578d3f037cfde5772dd240ad2db11235919b23b982b1d9adf'::TEXT, ARRAY[1198, 1199]::BIGINT[]),
    (354::BIGINT, 'Excelente profesor, claridad en la materia brinda ayuda cuando se necesita pero hay que estudiar.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-09-15T00:00:00+00:00'::TIMESTAMPTZ, '16c3259d744823110c6510e5375d82e072b9a3b470658842339f54a0aa889a85'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'Es buen profe solo que no deja mucho muchos ejercicios para practicar, si da un ejercicio es el que es básico'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'ac292eea7a0cb73e5cad73389c7bea994bb3e0f9c8ef9f6205fc34b478393325'::TEXT, ARRAY[1198]::BIGINT[]),
    (354::BIGINT, 'Le importa mucho la hora de consulta'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-03T00:00:00+00:00'::TIMESTAMPTZ, '2ab886cbd86b2144f13370269c9573d422a58822dc875ff7059d6fc61ed1db46'::TEXT, ARRAY[1198]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
